{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue (benzimidazole-piperidine, Morgan 0.39) has a rat B/Pb of 2.7, showing the shared core can cross the BBB as a lipophilic base; however, it lacks the query's ionized carboxylic acid and ethoxyethyl group, so this positive result does not transfer to the zwitterionic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Darifenacin, a lipophilic basic drug, has a rat Kp,free of only 0.02, demonstrating that lipophilic amines can have negligible unbound brain exposure; the query's additional carboxylic acid and zwitterionic character are expected to be at least as restrictive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Loperamide has a rat Kp,uu,brain of 0.004, a classic efflux-limited non-CNS profile; this supports the likelihood that the query's ionizable acid/base scaffold will also have poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "AZD1390 achieves a Kp,uu of 0.33 in non-human primates and is considered brain-penetrant, showing moderate unbound exposure can be meaningful; but AZD1390 is a lipophilic base without the query's acid, so it does not rescue the query's predicted poor permeability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "AVN-101 has a brain/blood AUC ratio of 20 but very low CSF exposure, illustrating that high total brain partitioning can occur without high unbound exposure; this is not transferable to the acid-containing query because AVN-101 is a lipophilic base.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a zwitterionic benzimidazole-piperidine with a basic piperidine and an ionized carboxylic acid, plus a polar ethoxyethyl group, predicting poor passive BBB permeability. The closest analogue (C03) is brain-penetrant but lacks the acid; direct positive CNS evidence from lipophilic bases does not transfer. New L2 evidence consists mostly of unrelated lipophilic basic CNS drugs or formulation studies and does not provide a close acid-containing analogue. Therefore meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No experimental brain/plasma/CSF data for the query or close analogues containing the same carboxylic acid/zwitterion.",
    "No P-gp/BCRP or active uptake transporter data for the query.",
    "No unbound brain or CSF measurements for the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C15", "C21"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "efflux-limited basic CNS drugs"
    },
    {
      "applicability": "low",
      "card_ids": ["C12", "C18", "C20", "C22", "C23"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "brain-penetrant lipophilic bases"
    },
    {
      "applicability": "not_applicable",
      "card_ids": ["C13", "C16", "C17"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "formulation-dependent brain exposure"
    },
    {
      "applicability": "not_applicable",
      "card_ids": ["C14", "C19"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "passive diffusion simulations"
    }
  ],
  "revision_action": "keep"
}

